sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    var reportId = "70ee48d6473c47100a1452e1d16d4337"; 

    template.print('<table style="width:100%; border-collapse: collapse; font-family: Arial; font-size: 12px;">');
    template.print('<thead><tr style="background-color: #800080; color: white;">');
    template.print('<th style="padding: 10px; border: 1px solid #ddd; text-align: left;">Student</th>');
    template.print('<th style="padding: 10px; border: 1px solid #ddd; text-align: left;">E-mail</th>');
    template.print('</tr></thead><tbody>');

    var gr = new GlideRecord('x_221517_nowtrai_0_enrollment');
    gr.addQuery('training', current.sys_id);
    gr.addQuery('state', 3);
    gr.query();

    var count = 0;
    while (gr.next()) {
        count++;
        var rowColor = (count % 2 === 0) ? '#f2f2f2' : '#ffffff'; 
        template.print('<tr style="background-color: ' + rowColor + ';">');
        template.print('<th style="padding: 8px; border: 1px solid #ddd; font-weight: normal;">' + gr.student.getDisplayValue() + '</th>');
        template.print('<th style="padding: 8px; border: 1px solid #ddd; font-weight: normal;">' + gr.student.email + '</th>');
        template.print('</tr>');
    }

    if (count === 0) {
        template.print('<tr><td colspan="2" style="padding: 10px; border: 1px solid #ddd; text-align: center;">There are no students enrolled yet.</td></tr>');
    }

    template.print('</tbody></table>');

})(current, template, email, email_action, event);
